"""Assemble the R Journal source ledger from recorded retrieval receipts.

Only manually described semantic reading is counted. HTTP success and
metadata exposure do not silently become a full-text reading.
"""
import datetime,hashlib,json
from pathlib import Path
P=Path(__file__).resolve().parent
base=[json.loads(x) for x in (P/'sources.jsonl').read_text().splitlines()]
rows=[x for x in base if x['source_id'] in {'RJ-C-001','RJ-C-003','RJ-C-004','RJ-C-005','RJ-C-006','RJ-C-007'}]

def add(sid,work,url,opened,locator,observation,limitation,*,case=None,publisher='',kind='source',edition='미확인',published='미확인',modified='미확인',count=False,allocation='extra',dup=None,status='direct_semantic_read',final=None,sha=None,precision='recorded request UTC',**extra):
    r=dict(source_id=sid,work_id=work,edition_id=edition,source_url=url,final_url=final or url,publisher=publisher,kind=kind,published=published,modified=modified,opened_utc=opened,first_open_precision=precision,locator=locator,observation=observation,limitation=limitation,questions=['Q1','Q3','Q4','Q5','Q7'],case_ids=case or [],duplicate_of=dup,minimum_count=count,allocation=allocation,access_status=status,response_sha256=sha)
    r.update(extra);rows.append(r)

meta=json.loads((P/'frame_all_metadata.json').read_text())
for i,r in enumerate(meta['index_receipts'],1):
    add(f'RJ-INDEX-{i}','RJournal-issue2022-'+str(i),r['url'],r['opened_utc'],'Research articles TOC; publication metadata harvested separately',f'Issue{i} exposes '+str(22 if i==1 else 18)+' research article records; date/identifier sort uses individual citation metadata.','Nominal issue month is not individual publication day; issue-page reading not a consumer source.',publisher='The R Journal',kind='frame_index',status='direct_index_read',sha=r['sha256_current_response'])
for r in meta['rows']:
    suffix=r['doi'].rsplit('-',1)[-1]
    if suffix in {'001','003','004','005','006','007'}:continue
    add(f'RJ-META-{suffix}',r['doi'],r['url'],r['opened_utc'],'HTML citation_title/citation_doi/citation_publication_date',r['title']+'; date='+r['publication_date']+'; exposure='+str(r['exposure_order']), 'Metadata-only retrieval does not count as semantic full-text reading. '+('Initial accidental TOC body exposure occurred before date/identifier ordering; not selected and no edition result used.' if suffix in {'002','008'} else 'After the first three eligible selections, later articles are exposure records only.'),publisher='The R Journal',kind='frame_metadata',published=r['publication_date'],status='metadata_only',sha=r['sha256_current_response'])

supp=json.loads((P/'supplement_receipts.json').read_text())
supp_details={
 '004':('RJ01','shrinking_cities.r lines12,16–26,37–38,47–66','Only shrinking_cities.r is in ZIP. It reads research_data.xlsx sheets data_1992/data_2018; screeplot prcomp excludes first row+column; biplot preparation uses all data rows.','Workbook is absent from this ZIP. No runID, input hash, exact Fig2 output or explanation of row-selection difference. ZIP timestamp is packaging metadata, not execution.'),
 '006':('RJ02','yenetal.R lines81–108, especially ratio/cal_entro/readRDS','Plot code computes true feature flags divided by length, removes NULL result objects and multiplies by100; external author RDS is required.','This code is a recipe, no saved execution receipt; current same-paper supplement adds no unique-work count.'),
 '007':('RJ03','rmonad.R lines62–95; unrelated foo/sessionInfo block lines20–28','Iris branch declares as_monad(iris), aov(Petal.Length~Species), summary and later get_value(m)[id].','No saved Iris Rmonad object, R datasets version, original runID or hash. The toy foo sessionInfo is not the Iris run and is not joined to it.')}
for r in supp:
    suffix=r['article'].rsplit('-',1)[-1];case,loc,obs,lim=supp_details[suffix]
    add('RJ-SUP-'+suffix,'10.32614/RJ-2022-'+suffix,r['url'],r['opened_utc'],loc,obs,lim,case=[case],publisher='The R Journal / article authors',kind='consumer_supplement',edition='published supplemental ZIP',published='2022-06-21',dup='RJ-C-'+suffix,status='direct_zip_member_read',sha=r['sha256'],files=r['files'])

add('RJ-P-INS1992','INS-RPL1992','https://www.recensamantromania.ro/rezultate-recensamant-1992/','2026-11-22T22:15:29Z','Volumul1 (1992), tables1–3; Volumul2 socioeconomic table list; web lines49–105','Official archive separately labels census1992 and lists city population/history and socioeconomic tables. This establishes candidate census-edition publication.','Does not map the consumer13-indicator workbook or first PC1 variance to exact publisher tables/files; a census reference period is not a download vintage. Earliest successful opening may have been the prior22:13 web batch; this timestamp is verified reread.',case=['RJ01'],publisher='Romanian National Institute of Statistics census website',kind='publisher_edition_catalogue',edition='RPL1992',published='1992 reference period; web-upload dates not publication proof',count=True,allocation='publisher',precision='verified web reread batch clock; first exact semantic UTC not captured')
add('RJ-P-INS2011','INS-RPL2011','https://www.recensamantromania.ro/rpl-2011/rezultate-2011/','2026-11-22T22:12:48Z','VolumeI demographics; Table1 historical populations1948–2011','Publisher exposes2011 census results and time-indexed historical population table.','Later census period is not automatically the next corrected edition of1992; not substituted for primary1992 input; conservatively excluded from minimum allocation.',case=['RJ01'],publisher='Romanian National Institute of Statistics',kind='publisher_period_comparison',edition='RPL2011',precision='web batch clock')
add('RJ-P-INS-XLS-FAIL','INS-RPL1992','https://www.recensamantromania.ro/wp-content/uploads/2023/09/VOL1_1992_Tabel-03.xls','2026-11-22T22:15:29Z','City historical population table3 link','The linked original workbook URL was reached by the web tool but content extraction rejected application/vnd.ms-excel.','No workbook cells read; this is an access/format failure, not value mismatch. Next action: read XLS locally with an XLS reader if the workbook becomes relevant.',case=['RJ01'],publisher='Romanian National Institute of Statistics',kind='failed_file_open',dup='RJ-P-INS1992',status='unsupported_content_type',precision='web batch time bounded between22:15:29 and22:16:11')
add('RJ-P-CRAN-INDEX','CRAN-corpus-1998-selection','https://cran.r-project.org/src/contrib/Archive/','2026-11-22T22:11:02Z','Package archive directory listing','Publisher archive exposes package-level subdirectories; individual fixed tarballs inspected later.','Current directory mtime and existence do not recreate the whole2020-07-01 mirror.',case=['RJ02'],publisher='CRAN / R Foundation',kind='publisher_catalogue',precision='web batch clock')
add('RJ-P-IRIS','Iris1936-data-family','https://stat.ethz.ch/R-manual/R-devel/library/datasets/html/iris.html','2026-11-22T22:11:02Z','Description/Format/Source; current footer datasets version4.6.0','R describes150 rows, four measurements in centimetres, and50 flowers for each of three species; iris3 changes representation.','Current manual release is not the consumer2022 version. The data family is counted once across R releases and UCI copies.',case=['RJ03'],publisher='R Core / official R documentation',kind='publisher_data_documentation',edition='current-served datasets4.6.0 manual',count=True,allocation='publisher',precision='web batch clock')
add('RJ-P-UCI','Iris1936-data-family','https://archive.ics.uci.edu/dataset/53/iris','2026-11-22T22:11:56Z','Additional Information row35/38 correction; Dataset Files; DOI; web lines47–49,77–84,160–173','UCI identifies correction differences at samples35 and38 and supplies iris.data plus bezdekIris.data under DOI10.24432/C56C76.','The two variants are not a dated next-edition sequence, and UCI was not the consumer-declared route data(iris). Correction text is in the same dataset record, so no extra unique work.',case=['RJ03','AUX-RJ-IRIS'],publisher='UCI Machine Learning Repository',kind='publisher_correction_record',edition='DOI10.24432/C56C76 current record',published='donated1988-06-30; correction date unspecified',dup='RJ-P-IRIS',precision='web batch clock')
add('RJ-P-R-INDEX','Iris1936-data-family','https://cran.r-project.org/src/base/R-4/','2026-11-22T22:15:29Z','R4.2.0/R4.2.1 directory rows; web lines18–19','R4.2.0 index date2022-04-22; next4.2.1 date2022-06-23. Candidate pair brackets article2022-06-21.','Pair is analyst-selected by publication timing, not author-declared actual run edition. Whole R tarballs differ, while Iris members are checked separately.',case=['RJ03'],publisher='CRAN / R Core',kind='publisher_release_catalogue',dup='RJ-P-IRIS',precision='verified web reread batch clock')

receipts=json.loads((P/'publisher_http_receipts.json').read_text())
for r in receipts:
    if r['source_key']=='zenodo':
        add('RJ-A-RSTYLE','10.5281/zenodo.4026588',r['url'],r['opened_utc'],'metadata.version/publication_date/related_identifiers; files[0] checksum/id/size; conceptdoi','Edition DOI4026589, concept DOI4026588, v1.0, published2020-09-12 and described as second R Journal submission code+data. Related GitHub tag1.0. Publisher reports MD5 of215354855-byte archive.','Entire ZIP not downloaded; reported MD5 is not our computed hash. Fixed GitHub commit files were independently downloaded. Author archive is not a publisher-issued CRAN mirror and has no original run receipt.',case=['RJ02'],publisher='Zenodo / Yen, Chang, Chan',kind='author_archived_analysis',edition='10.5281/zenodo.4026589 v1.0',published='2020-09-12',modified='2020-09-13T00:59:28.258684+00:00',count=True,allocation='author_record',sha=r.get('sha256'))
    elif r.get('status')==200:
        add('RJ-A-'+r['source_key'].upper(),'10.5281/zenodo.4026588',r['url'],r['opened_utc'],'GitHub tags/tree JSON','Inspected archive tag1.0 resolution and current repository file paths to locate author inputs.','Current tree is not a historical run. Same author code/data work as Zenodo release, no extra minimum count.',case=['RJ02'],publisher='GitHub / chainsawriot',kind='author_repository_metadata',dup='RJ-A-RSTYLE',sha=r.get('sha256'))
    else:
        add('RJ-FAIL-'+r['source_key'].upper(),r['url'],r['url'],r['opened_utc'],'HTTP retrieval attempt','Retrieval failed: '+str(r.get('error',r.get('status'))),'No semantic content or values confirmed; retry canonical publisher or fixed release archive, not inferred mismatch.',case=['RJ01' if 'ins' in r['source_key'] else 'RJ03'],kind='failed_open',status='failed')

for r in json.loads((P/'object_comparison_receipts.json').read_text()):
    if r['label']=='rstyle-1.0-tree':
        add('RJ-A-RSTYLE-FIXEDTREE','10.5281/zenodo.4026588',r['source_url'],r['opened_utc'],'recursive tree at commit07a60457c88dbb20858441047f248d61ce2955c7','Fixed release tree includes target_meta.RDS and yearly syntax records; no CRAN tarball collection or code.db is in this tree.','Tree absence is scoped to this tree, not a claim of internet-wide absence. DOI ZIP not fully downloaded.',case=['RJ02'],publisher='GitHub / chainsawriot',kind='author_fixed_artifact_manifest',edition='commit07a60457c88dbb20858441047f248d61ce2955c7',published='2020-09-12',dup='RJ-A-RSTYLE',sha=r.get('sha256'))
    else:
        isr=r['kind']=='r_tar'
        add('RJ-P-'+r['label'].upper().replace('.',''), 'Iris1936-data-family',r['source_url'],r['opened_utc'],'tar src/library/datasets/data/iris.R or ZIP iris.data/bezdekIris.data; rows35,38; Species definition','Downloaded full publisher object and computed SHA256; inspected literal data. '+('R4.2.0 and4.2.1 iris.R SHA256 identical:77af4424d5361afe1c46e7fb95bc4f95681f5515a586cb41c062b111c691dc5c. Both yield SpeciesDf2.' if isr else 'Two UCI files differ at corrected rows; both have150 observations, three groups, SpeciesDf2.'),'Audit comparison is2026, not original consumer run. All variants remain one counted data family. See iris_value_comparison.json for exact local derived values.',case=['RJ03','AUX-RJ-IRIS'],publisher='R Core / CRAN' if isr else 'UCI Machine Learning Repository',kind='publisher_data_file',edition=r['label'],dup='RJ-P-IRIS',status='full_bytes_and_data_semantic_read',sha=r.get('sha256'),members=r.get('members'))

author_locs={
'README.md':('lines13–41,53–57','Requires mirror and code.db reconstruction; identifies target_meta.RDS as random package/year sample; old2019 poster title persists.'),
'config.R':('lines1–10','INCLUDE_YR=2019 and target metadata/feature input paths.'),
'extract_metadata.R':('lines11–36','Extracts paths/mtime/pkg names, fixes seed46709394, saves one sampled version per package/year.'),
'helpers.R':('grab_source_ns, extract_exported_functions','Looks up source and NAMESPACE in code.db by package/year; logic recipe, not an execution log.'),
'syntax03_vis.R':('lines11,21–31,42–55','Computes feature ratio after dropping NULL results; year range1998..INCLUDE_YR.'),
'target_meta.RDS':('top-level columns; all49696 rows inspected structurally; year1998 16 rows','Input manifest has path,modification_time,pkg_name,year,desc; sixteen1998 versioned tarball names, all matching yearly feature records.'),
'data/syntax_feature_yr1998.RDS':('16package rows / function_feat.result.fx_assign','All386 recorded exported functions have fx_assign=False; aggregate0/386=0%. Includes same16 tarball names as target_meta.'),
'rjournal_submission/figures.R':('lines39–74 (Fig1)','Author plotting recipe computes the displayed share; input file and filters preserved.'),
'rjournal_submission/yenetal.tex':('Data Source; Reproducibility sections','Archived manuscript names the same data collection and versioned analysis archive; same paper lineage.')}
for i,r in enumerate(json.loads((P/'author_artifact_receipts.json').read_text()),1):
    loc,obs=author_locs[r['path']]
    add(f'RJ-A-FILE-{i:02d}','10.5281/zenodo.4026588',r['source_url'],r['opened_utc'],r['path']+' '+loc,obs,'Same author artifact lineage; not independent publisher validation. RDS parser preserves named vectors/lists; details and warnings in rstyle_author_value_reading.json. No original execution ID.',case=['RJ02'],publisher='Yen, Chang, Chan / GitHub',kind='author_input_record' if r['path'].endswith('.RDS') else 'author_code_or_text',edition='commit07a60457c88dbb20858441047f248d61ce2955c7',published='commit2020-09-12',dup='RJ-A-RSTYLE',status='direct_file_semantic_read',sha=r.get('sha256'))

for r in json.loads((P/'cran_1998_publisher_receipts.json').read_text()):
    sid='RJ-P-CRAN-'+r['package'].upper()
    desc=r.get('description_package_version',[])
    add(sid,'CRAN-corpus-1998-selection',r['source_url'],r['opened_utc'],'tar DESCRIPTION Package/Version plus R/ member inventory', 'Exact filename named by author manifest exists; '+', '.join(desc)+'. Full-object SHA256 computed.','Consumer did not record these byte hashes. Source-token screening is not a lintr/export-selection replication, so cannot independently certify full 0/386. Sixteen files are one conservative input-corpus work, not sixteen quota credits.',case=['RJ02'],publisher='CRAN / package authors',kind='publisher_input_file',edition=r['declared_local_path'].rsplit('/',1)[-1],count=r['package']=='acepack',allocation='publisher' if r['package']=='acepack' else 'edition_component',dup=None if r['package']=='acepack' else 'RJ-P-CRAN-ACEPACK',status='full_bytes_and_description_read' if r.get('status')==200 else 'failed',sha=r.get('sha256'),component_work_id='R-package-'+r['package'],coverage_unit='one of sixteen declared1998tarballs')

add('RJ-P-ACEPACK-INDEX','CRAN-corpus-1998-selection','https://cran.r-project.org/src/contrib/Archive/acepack/','2026-11-22T22:23:26Z','index acepack1.1 and next1.2-1; web lines9–10','Publisher lists acepack1.1 at1998-03-25, next1.2-1 at1999-08-19. Internal DESCRIPTION of1.1 says1.0-4.','Archive filename and package-internal Version are different keys; no official reason for the mismatch found. The next release changes targetyear and cannot simply replace the1998 historical sample.',case=['RJ02','AUX-RJ-ACEPACK'],publisher='CRAN',kind='publisher_release_catalogue',dup='RJ-P-CRAN-ACEPACK',precision='web batch clock')
add('RJ-P-OLD061-INDEX','CRAN-corpus-1998-selection','https://cran.r-project.org/src/contrib/Old/0.61/','2026-11-22T22:23:26Z','class/nnet5.2pl005-2; web lines8,11','Publisher lists class and nnet filename version5.2pl005-2; downloaded DESCRIPTION says5.2pl005-1 for both.','This is an observed label mismatch, not an inferred numerical correction. No consumer-byte checksum.',case=['RJ02'],publisher='CRAN',kind='publisher_release_catalogue',dup='RJ-P-CRAN-ACEPACK',precision='web batch clock')

for i,line in enumerate((P/'additional_http_receipts.jsonl').read_text().splitlines(),1):
    r=json.loads(line);url=r['source_url'];tooldep='pypi.org' in url
    add(f'RJ-ADDITIONAL-{i}', 'analysis-tooling' if tooldep else ('rmonad-software' if 'arendsee' in url else '10.5281/zenodo.4026588'),url,r['opened_utc'],'API JSON / repository tree / commit date', ('Audit parser package metadata and wheel located; not research evidence.' if tooldep else ('Rmonad current tree exposes manuscripts/vignettes, no named Iris RDS/cache found in tree.' if 'arendsee' in url else 'Tag1.0 commit07a60457... commit date2020-09-12T19:13:24Z verified.')),'Metadata/tooling only; not an additional minimum work; no historical run identity.',case=[] if tooldep else ['RJ03' if 'arendsee' in url else 'RJ02'],publisher='PyPI' if tooldep else 'GitHub',kind='audit_tooling' if tooldep else 'author_repository_metadata',dup=None if tooldep or 'arendsee' in url else 'RJ-A-RSTYLE',status='metadata_only')

(P/'sources.jsonl').write_text(''.join(json.dumps(r,ensure_ascii=False)+'\n' for r in rows))
assert len({r['source_id'] for r in rows})==len(rows)
counts={a:sum(r['minimum_count'] and r['allocation']==a for r in rows) for a in ['consumer','publisher','author_record']}
(P/'source_count.json').write_text(json.dumps({'computed_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'ledger_rows':len(rows),'unique_minimum_works':sum(counts.values()),'allocations':counts,'notes':['16CRANtarballs grouped as one input-corpus work','Rrelease/Iris/UCIvariants grouped as one input-data family','same-paper supplements and metadata-only exposures add zero','firstwebUTC precision gaps explicitly retained']},ensure_ascii=False,indent=2)+'\n')
print(len(rows),counts)
